window.RP_SESSION={"id":"S-a6eec26565db","messages":[{"id":"RP-II-0078985","time":"2026-04-10T19:23:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아, 미치겠다. 마리우스는 조용히 웅얼였다. 고작 끊고자 시도한 것이 며칠 지나지도 않았는데. 단 것이 당기고···. 집중이 쉽게 되지도 않고. 덕분에 훈련 도중 얼마나 멍을 떄린 건지···.\n\n조용히 손에 들린 마지막 연초를 버리고선. 싫증이 난다는 듯 옆에 주저 앉는다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078986","time":"2026-04-10T19:24:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"성격도 더러워진 기분. 참을성은 적어지고 원래라면 웃고 넘길 것도 꼴이 보기 싫다. 조용히 손을 뻗어 모래를 쥐고, 휙···. 앞으로 던져낸다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078987","time":"2026-04-10T19:27:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아니. 기분이 아닐지도 모르겠다···.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078988","time":"2026-04-10T19:36:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"(—) 거지같은 거. 욕 읊고서는 한숨 내쉽니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078989","time":"2026-04-10T19:37:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아! 왜 버렸어어어. 다시 그냥 주저 앉아서 힘 없이 숨만 쉽니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078990","time":"2026-04-10T20:02:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이번엔 차라리 비가 좀 오면 좋겠습니다. 한숨 내쉬고.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078991","time":"2026-04-10T20:05:00+09:00","room":"RP II","name":"어설픈 용 ⃢맹","profile":"어설픈 용 ⃢맹","identity":"unresolved","type":"dialogue","body":"☀️☁️","characters":[]},{"id":"RP-II-0078992","time":"2026-04-10T20:08:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078993","time":"2026-04-10T20:14:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0078994","time":"2026-04-10T20:14:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
